import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

__device__ float mish_func(float x) {
    float sp = log1pf(expf(x));
    float tsp = tanhf(sp);
    return x * tsp;
}

__global__ void fused_subtract_mish_kernel(const float* input, float* output, int n, float sub1, float sub2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < n) {
        float val = input[idx] - sub1 - sub2;
        output[idx] = mish_func(val);
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor input, float sub1, float sub2) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int threads = 256;
    int blocks = (num_elements + threads - 1) / threads;

    fused_subtract_mish_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        sub1,
        sub2
    );

    return output;
}
"""

fused_ops_cpp = "torch::Tensor fused_ops_cuda(torch::Tensor input, float sub1, float sub2);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp,
    cuda_sources=fused_ops_source,
    functions=['fused_ops_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, subtract_value_1, subtract_value_2):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.subtract_value_1 = subtract_value_1
        self.subtract_value_2 = subtract_value_2
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_ops.fused_ops_cuda(x, self.subtract_value_1, self.subtract_value_2)
        return x
